<?php declare(strict_types=1); ?>
<?php if ($preview && $write): ?><section class="rounded-panel border border-border bg-surface p-4"><h2>Review supplier bill</h2><p><?= pl_e($preview['supplier'] . ' · ' . $preview['input']['reference'] . ' · ' . $preview['input']['date']) ?></p><p>Currency <?= pl_e($preview['input']['currency']) ?> · Rate <?= pl_e($preview['rate_snapshot']['rate']) ?></p><div class="table-wrap"><table class="table"><thead><tr><th>Received goods</th><th>Bill quantity</th><th>Net amount</th><th>Tax</th><th>Receipt carrying value</th><th>Price/rate variance</th></tr></thead><tbody><?php foreach ($preview['lines'] as $line): ?><tr><td><?= pl_e($line['description']) ?></td><td><?= pl_e($line['quantity']) ?></td><td><?= pl_e($line['net_fc']) ?></td><td><?= pl_e($line['tax']['tax_amount']) ?></td><td><?= pl_e($line['receipt_basis_base']) ?></td><td><?= pl_e($line['variance_base']) ?></td></tr><?php endforeach; ?></tbody></table></div><p>Total payable <strong><?= pl_e($preview['input']['currency'] . ' ' . $preview['total_fc']) ?></strong> · Purchase variance <?= pl_e($company['currency'] . ' ' . $preview['variance_base']) ?></p><form method="post" action="<?= pl_e(pl_url('/purchasing')) ?>"><?php pl_ui_return_filters($filters); pl_starter_form($company, 'bill_confirm', ['id' => $order['id'] ?? 0, 'expected_hash' => $billConfirmInput?($billConfirmInput['expected_hash']??''):$preview['payload_hash'],'request_key'=>$billConfirmInput['request_key']??$preview['input']['idempotency_key']]); ?><p><label><input type="checkbox" name="confirmed" value="1" required <?= ($billConfirmInput['confirmed']??'')==='1'?'checked':'' ?>> I reviewed the supplier, matched quantities, payable amount, taxes and price/rate differences.</label></p><button class="btn btn-primary">Post supplier bill and match receipts</button><?php if ($billConfirmInput): ?><a class="btn btn-secondary" href="<?= pl_e(pl_url('/purchasing',$order?['id'=>$order['id'],'return_filters'=>$filters]:$filters)) ?>">Reload current bill review</a><?php endif; ?></form></section><?php endif; ?>
<?php if ($write && $billRows): ?><details class="rounded-panel border border-border bg-surface p-4" <?= $order || $billInput ? 'open' : '' ?>><summary>Create supplier bill from receipts</summary><p>Enter quantities to bill below; leave unused receipt lines blank. All selected receipts must belong to the same supplier, currency and clearing account. Stock is already recorded.</p><form method="post" action="<?= pl_e(pl_url('/purchasing')) ?>"><?php pl_ui_return_filters($filters); pl_starter_form($company, 'bill_preview', ['id' => $order['id'] ?? 0,'request_key'=>$billInput['request_key']??$billInput['idempotency_key']??null]); ?><div class="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4"><?php pl_starter_select('Supplier', 'party_id', $supplierOptions, $billInput['party_id']??$order['party_id']??''); pl_starter_field('Bill date', 'date', $billInput['date']??gmdate('Y-m-d'), 'date'); pl_starter_field('Due date', 'due_date', $billInput['due_date']??gmdate('Y-m-d'), 'date'); pl_starter_field('Currency', 'currency', $billInput['currency']??$order['currency']??$company['currency']); pl_starter_field('Supplier reference', 'reference', $billInput['reference']??'', 'text', false); pl_starter_select('Supplier bill prices', 'price_mode', ['exclusive' => 'Tax-exclusive: add selected tax', 'inclusive' => 'Tax-inclusive: entered price includes tax'], $billInput['price_mode']??$priceMode); pl_starter_select('Received-but-unbilled liability account', 'grni_account_id', $grniOptions, $billInput['grni_account_id']??$billRows[0]['grni_account_id']); pl_starter_field('Manual bill rate to ' . $company['currency'], 'rate', $billInput['rate']??'', 'text', false); pl_starter_select('Purchase variance account', 'variance_account_id', $varianceOptions, $billInput['variance_account_id']??'', false); pl_starter_select('Currency rounding expense account', 'rounding_account_id', $roundingOptions, $billInput['rounding_account_id']??'', false); ?></div>
<?php foreach (array_slice($billRows, 0, 100) as $i => $receipt): $billLine=$billLines[(int)$receipt['id']]??[]; ?><fieldset class="rounded-panel border border-border p-3 my-3"><legend>Receipt <?= (int) $receipt['receipt_id'] ?> · <?= pl_e($receipt['description']) ?></legend><p><?= pl_e($receipt['document_date']) ?> · Supplier <?= pl_e($supplierOptions[(string) $receipt['party_id']] ?? '') ?> · Unbilled <?= pl_e($receipt['unbilled_quantity']) ?> · Receipt cost <?= pl_e($receipt['currency'] . ' ' . $receipt['unit_price']) ?></p><?php pl_starter_hidden("lines[$i][receipt_line_id]", $receipt['id']); ?><div class="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4"><?php pl_starter_field('Quantity on bill', "lines[$i][quantity]", $billLine['quantity']??'', 'text', false); pl_starter_field('Unit price on bill', "lines[$i][unit_price]", $billLine['unit_price']??$receipt['unit_price'], 'text', false); pl_starter_select('Input tax code', "lines[$i][tax_code_id]", pl_starter_options($taxCodes), $billLine['tax_code_id']??'', false); ?></div></fieldset><?php endforeach; ?>
<p><label><input type="checkbox" name="variance_confirmed" value="1" <?= in_array($billInput['variance_confirmed']??false,[true,'1'],true)?'checked':'' ?>> Any price/rate difference is intentional and should use the selected variance account.</label></p><button class="btn btn-primary">Preview supplier bill</button></form></details><?php endif; ?>
