<?php foreach ($receipt['matches'] as $match): ?><p><a href="<?= pl_e(pl_url('/ap', ['id' => $match['bill_document_id']])) ?>">Supplier bill <?= (int) $match['bill_document_id'] ?></a> · Matched quantity <?= pl_e($match['quantity']) ?> · Unit price <?= pl_e($match['unit_price']) ?></p><?php endforeach; ?>
<?php foreach ($receipt['returns'] as $return): ?><p>Returned <?= pl_e($return['quantity'] . ' on ' . $return['document_date']) ?> · <?= pl_e($return['reason']) ?><?php if ($return['credit_document_id']): ?> · <a href="<?= pl_e(pl_url('/ap', ['id' => $return['credit_document_id']])) ?>">Supplier credit</a><?php endif; ?></p><?php endforeach; ?>
<?php if ($write): $matchOptions = ['0' => 'Unbilled goods: no supplier credit']; foreach ($receipt['matches'] as $match) { $matchOptions[(string) $match['id']] = 'Bill ' . $match['bill_document_id'] . ', line ' . $match['bill_line_number']; } ?><form method="post" action="<?= pl_e(pl_url('/purchasing')) ?>"><?php pl_ui_return_filters($filters); pl_starter_form($company, 'return', ['id' => $order['id'] ?? 0, 'receipt_line_id' => $receipt['id'],'request_key'=>$returnInput['request_key']??null]); ?><div class="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4"><?php pl_starter_select('Return against', 'match_id', $matchOptions, $returnInput['match_id']??'0'); pl_starter_field('Quantity to return', 'quantity',$returnInput['quantity']??''); pl_starter_field('Return date', 'date', $returnInput['date']??gmdate('Y-m-d'), 'date'); pl_starter_field('Return reason', 'reason',$returnInput['reason']??''); pl_starter_select('Variance account if rounding differs', 'variance_account_id', $varianceOptions, $returnInput['variance_account_id']??'', false); pl_starter_select('Currency rounding expense account', 'rounding_account_id', $roundingOptions, $returnInput['rounding_account_id']??'', false); ?></div><p><label><input type="checkbox" name="variance_confirmed" value="1" <?= ($returnInput['variance_confirmed']??'')==='1'?'checked':'' ?>> Apply a carrying-value rounding difference to the selected variance account.</label></p><p><label><input type="checkbox" name="confirmed" value="1" required <?= ($returnInput['confirmed']??'')==='1'?'checked':'' ?>> These goods are returned; create the linked supplier credit when billed.</label></p><button class="btn btn-secondary">Record purchase return</button></form><?php endif; ?></details><?php endforeach; ?></section>
<section class="rounded-panel border border-border bg-surface p-4"><h2>Received-but-unbilled reconciliation</h2><form method="get" action="<?= pl_e(pl_url('/purchasing')) ?>"><?php if ($order) { pl_starter_hidden('id',$order['id']); pl_ui_return_filters($filters); } else { foreach ($filters as $key=>$value) { if ($key!=='as_of') { pl_starter_hidden($key,$value); } } } pl_starter_field('As of',$order?'return_filters[as_of]':'as_of',$reconciliation['as_of'],'date'); ?><button class="btn btn-secondary">Refresh reconciliation</button></form><div class="table-wrap"><table class="table"><thead><tr><th>Clearing account</th><th>Receipt balance</th><th>Ledger balance</th><th>Difference</th></tr></thead><tbody><?php foreach ($reconciliation['accounts'] as $account): ?><tr><td><a href="<?= pl_e(pl_url('/reports/account', ['id' => $account['account_id']])) ?>"><?= pl_e($grniOptions[(string) $account['account_id']] ?? (string) $account['account_id']) ?></a></td><td><?= pl_e($account['unbilled_base']) ?></td><td><?= pl_e($account['ledger_base']) ?></td><td><strong><?= pl_e($account['difference']) ?></strong></td></tr><?php endforeach; ?><?php if (!$reconciliation['accounts']): ?><tr><td colspan="4">No receipt balances to reconcile.</td></tr><?php endif; ?></tbody></table></div></section>

